INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '计算', 2, '{"stem": "用竖式计算：45÷3=", "options": null}', '15', '45=30+15，30÷3=10，15÷3=5，10+5=15，所以 45÷3=15。（竖式：十位 4÷3 商1余1个十，个位 15÷3 商5）', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p070.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
