INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '填空', 1, '{"stem": "想一想，填一填：一共有 56 个□（如右图排列），分成（　）行，平均每行（　）个。", "options": null}', '4；14', '看图可知这些方格分成了 4 行。56÷4=14（个），所以分成（4）行，平均每行（14）个。（列式：56÷4，想 4×14=56）', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p070.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '选择', 2, '{"stem": "根据横式“64÷4=”，下列竖式计算正确的是（　）。", "options": ["A. 商是15（竖式见附图）", "B. 商是16（竖式见附图）"]}', 'B', '64÷4：十位 6÷4 商1，余 2 个十；把个位 4 落下来组成 24，24÷4=6，所以商是 16，没有余数，选 B。选项 A 的竖式把个位 24÷4 错算成商 5（4×5=20，24-20=4，余 4），商 15 余 4 是错误的。', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p071.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '选择', 2, '{"stem": "46 支铅笔，每个小朋友分 2 支，可以分给多少个小朋友？小亮用竖式计算出了结果（竖式见附图）。竖式中圈出来的部分表示的意思是（　）。", "options": ["A. 已经分掉了4支", "B. 已经分掉了40支", "C. 已经分掉了46支", "D. 还剩4支"]}', 'B', '46÷2：十位上的 4 表示 4 个十，即已经分掉了 40 支铅笔（2×20=40），所以选 B。', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p071.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '计算', 1, '{"stem": "列式计算：85 被 5 除，商是多少？", "options": null}', '17', '85÷5=17。想：85=50+35，50÷5=10，35÷5=7，10+7=17。', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p071.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '计算', 2, '{"stem": "列式计算：27 比 3 除 39 的商多多少？", "options": null}', '14', '先算 39÷3=13（3 除 39，即 39 除以 3）；再算 27-13=14。所以 27 比 3 除 39 的商多 14。', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p071.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '计算', 2, '{"stem": "列式计算：78 除以一个数得 6，这个数是多少？", "options": null}', '13', '78÷□=6，除数是 78÷6=13。想：78=60+18，60÷6=10，18÷6=3，10+3=13，所以这个数是 13。', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p071.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '应用题', 2, '{"stem": "一个农场有白兔 35 只，黑兔 53 只。每个笼子可以装 4 只兔子，共需要多少个笼子才能装下所有兔子？", "options": null}', '22个', '先求兔子总数：35+53=88（只）；再求笼子数：88÷4=22（个）。88=80+8，80÷4=20，8÷4=2，20+2=22。答：共需要 22 个笼子。', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p072.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '应用题', 2, '{"stem": "小兔 3 天采了 36 个蘑菇，照这样计算，一星期能采多少个蘑菇？", "options": null}', '84个', '先求 1 天采几个：36÷3=12（个）；一星期 7 天：12×7=84（个）。答：一星期能采 84 个蘑菇。', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p072.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1026, '数学', '三年级', '应用题', 3, '{"stem": "幼儿园买来 100 个球，其中 2 个是篮球，余下的球中一半是小足球，其余的是花皮球。花皮球有多少个？", "options": null}', '49个', '先求篮球以外的球：100-2=98（个）；余下球中一半是小足球，说明另一半是花皮球：98÷2=49（个）。答：花皮球有 49 个。', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p072.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1027, '数学', '三年级', '填空', 3, '{"stem": "把 4、11、2、3 分别填在下面的空格里，使算式成立：□÷□=□……□", "options": null}', '11÷4=2……3', '11 最大，作被除数；试：11÷4=2……3（余数 3 比除数 4 小），正好用上 4、11、2、3 四个数。若 11÷2=5……1 或 11÷3=3……2，商和余数都不在给定的数中，所以只有 11÷4=2……3。', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p072.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1027, '数学', '三年级', '填空', 3, '{"stem": "在一道有余数的除法中，被除数、除数、商与余数四个数的和是 96，商是 6，余数是 3，除数是（　）。", "options": null}', '12', '被除数=除数×6+3。四个数的和=除数×6+3+除数+6+3=96，即 7×除数+12=96，7×除数=84，除数=12。（检验：被除数=12×6+3=75，75+12+6+3=96 ✓）', 'paper', '["practice", "ykl3sx", "4.3"]', '["paper_png/ykl3_sx/p072.png"]', 0);
